// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skillimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport kotlin.reflect.KClass/** * NOUS — Brain skill contract. * * A skill is a unit of work that handles one or more [Intent] types. Skills * are more capable than rules — they can be async, multi-step, use LLMs * internally, and ask for user input (NeedsInput). * * Built-in skills (CallSkill, SmsSkill, OpenAppSkill, etc.) ship with the * app. Custom skills (JSON-based or JS-based) are added at runtime. * * Skills are registered in [SkillRegistry] via Hilt multibinding * (`@Binds @IntoSet` in feature modules). The registry auto-discovers all * skills at app startup. * * @see <a href="docs/spec/module2-spec-review.pdf">§6 Layer 2</a> */interface BrainSkill {    /** Unique skill ID (e.g., "call", "send_sms", "open_app"). */    val id: String    /** Human-readable name (shown in Settings → Skills). */    val displayName: String    /** What this skill does (shown in skill picker UI). */    val description: String    /** What this skill can do (used for skill selection ranking). */    val capabilities: Set<SkillCapability>    /** Android permissions required to execute this skill. */    val requiredPermissions: Set<String>    /** Which intents this skill handles. Used by SkillRouter for matching. */    val supportedIntents: Set<KClass<out Intent>>    /** Maximum execution time before timeout (default 5 seconds). */    val timeoutMs: Long        get() = DEFAULT_TIMEOUT_MS    /**     * Execute the skill for the given [intent].     *     * @param intent the classified intent (with slots filled)     * @param context skill context (dispatchers, brain bus, credentials)     * @return success / partial / needs-input / needs-permission / failure     */    suspend fun execute(        intent: Intent,        context: SkillContext,    ): Result<SkillOutput>    companion object {        const val DEFAULT_TIMEOUT_MS = 5_000L    }}/** * What a skill can do. Used for skill selection ranking. */data class SkillCapability(    val name: String,         // e.g., "make_calls"    val description: String,)/** * NOUS — Skill output. * * Result of [BrainSkill.execute]. Can be: *   - Success: skill completed, here's the result *   - Partial: skill completed with warnings (e.g., LLM timed out, fell back) *   - NeedsInput: skill paused, ask user a follow-up (Fixes #8) *   - NeedsPermission: skill cannot run, missing permission (Fixes #20) *   - Failure: skill failed */sealed interface SkillOutput {    /** Skill completed successfully. */    data class Success(        val message: String,        val data: Map<String, Any?> = emptyMap(),        val spokenMessage: String? = null,  // optional override for TTS    ) : SkillOutput    /** Skill completed with warnings. */    data class Partial(        val message: String,        val warnings: List<String>,        val data: Map<String, Any?> = emptyMap(),    ) : SkillOutput    /**     * Skill paused — needs user input to resume.     *     * Brain persists state to ConversationState table and waits for user's     * next input. When received, calls [ResumableSkill.resume].     *     * @see <a href="docs/spec/module2-spec-review.pdf">§5.2 NeedsInput State Machine</a>     */    data class NeedsInput(        val skillId: String,        val prompt: String,        val inputType: InputType,    ) : SkillOutput    /**     * Skill cannot run — missing Android permission.     *     * Brain emits SkillNeedsPermission event so UI shows permission prompt.     * After grant, UI re-emits the original intent to Brain.     *     * @see <a href="docs/spec/module2-spec-review.pdf">§6.1 Permission Fix</a>     */    data class NeedsPermission(        val skillId: String,        val missingPermissions: List<String>,        val userMessage: String,    ) : SkillOutput    /** Skill failed. */    data class Failure(        val error: AppError,        val userMessage: String? = null,    ) : SkillOutput}/** Type of input the skill is waiting for. */enum class InputType {    TEXT,    CONTACT,    PHONE_NUMBER,    DATE,    TIME,    DURATION,    CHOICE,    CONFIRMATION,}/** * Optional interface for skills that can resume after NeedsInput. * * @see <a href="docs/spec/module2-spec-review.pdf">§5.2 NeedsInput State Machine</a> */interface ResumableSkill : BrainSkill {    suspend fun resume(        state: ConversationState,        userInput: String,        context: SkillContext,    ): Result<SkillOutput>}/** * Persisted state of a paused conversation (skill returned NeedsInput). * * Stored in Room `conversation_states` table. Has 5-minute TTL — after which * state is marked EXPIRED and a fresh routing happens on next input. */data class ConversationState(    val sessionId: com.roshan.persona.brain.context.SessionId,    val correlationId: CorrelationId,    val skillId: String,    val intent: Intent,    val stage: ConversationStage,    val partialOutput: SkillOutput?,    val createdAt: java.time.Instant,)enum class ConversationStage {    PROCESSING,    NEEDS_INPUT,    RESUMING,    COMPLETED,    EXPIRED,}